pub const COMBAT_TABLE: &[FeatTableEntry] = &[
    FeatTableEntry { key: "Amateur Swashbuckler", category: FeatCategory::Combat, name: "Amateur Swashbuckler", description: Some("Though not a swashbuckler, you have and can use panache."), effect: Some(&[FeatEffectBonus { qualifiers: &["VAR", "PanacheMax", "max(1,CHA)"] }]), prerequisites: Some(&["!PREABILITY:1,CATEGORY=Special Ability,TYPE.Panache"]) },
    FeatTableEntry { key: "Anticipate Dodge", category: FeatCategory::Combat, name: "Anticipate Dodge", description: Some("You automatically know whether a creature you can see has a dodge bonus to its AC. You gain up to a +2 bonus on attack rolls against a target that has a dodge bonus. This bonus cannot exceed the dodge bonus of the creature you attack."), effect: None, prerequisites: Some(&["PREABILITY:2,CATEGORY=FEAT,Dodge,Mobility", "PREMULT:1,[PRETOTALAB:7],[PREVARGTEQ:MonkFeatQualify,4]"]) },
    FeatTableEntry { key: "Barroom Brawler", category: FeatCategory::Combat, name: "Barroom Brawler", description: Some("You have learned how to mimic the combat tricks and forms of others."), effect: None, prerequisites: Some(&["PRETOTALAB:4"]) },
    FeatTableEntry { key: "Battle Cry", category: FeatCategory::Combat, name: "Battle Cry", description: Some("%1 times per day, you can let out a battle cry as a swift action. When you do, allies within 30 feet who can hear you gain a +1 morale bonus on attack rolls and a +4 morale bonus on saving throws against fear. This effect lasts for 1 minute.&nl; If an ally is under the effect of this feat and fails a saving throw against a fear effect, she can choose to end the battle cry's effect on her to reroll the failed save. The ally must take the result of the reroll, even if it's lower. Each ally can use this effect only once per use of this feat.|BattleCryTimes"), effect: Some(&[FeatEffectBonus { qualifiers: &["VAR", "BattleCryTimes", "CHA"] }]), prerequisites: Some(&["PREMULT:1,[PRETOTALAB:5],[PRESKILL:1,Perform (Oratory)=5],[PRESKILL:1,Perform (Sing)=5],[PRESKILL:1,Perform (Act)=5]", "PRESTAT:1,CHA=13"]) },
    FeatTableEntry { key: "Befuddling Strike", category: FeatCategory::Combat, name: "Befuddling Strike", description: Some("Befuddling Strike forces a foe damaged by your unarmed attack to attempt a DC %1 Fortitude saving throw, in addition to dealing damage normally. You must declare that you are using this feat before you make your attack roll-thus, a failed attack roll ruins the attempt. A defender who fails this saving throw is confused for 1d4 rounds. You can use Befuddling Strike %2 times per day, but no more than once per round. Constructs, incorporeal creatures, mindless creatures, plants, undead, and creatures that are immune to critical hits cannot be affected by this ability.|CL/2+10+WIS|BefuddlingStrikeTimes"), effect: Some(&[FeatEffectBonus { qualifiers: &["VAR", "BefuddlingStrikeTimes", "CL/4"] }]), prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Improved Unarmed Strike", "PREMULT:1,[PREVARGTEQ:PreStatScore_DEX,13],[PREVARGTEQ:FeatDexRequirement,13]", "PRESTAT:1,WIS=13", "PRETOTALAB:8"]) },
    FeatTableEntry { key: "Blooded Arcane Strike", category: FeatCategory::Combat, name: "Blooded Arcane Strike", description: Some("While you are bloodraging, you don't need to spend a swift action to use your Arcane Strike-it is always in effect. When you use this ability with Vital Strike, Improved Vital Strike, or Greater Vital Strike, the bonus on damage rolls for Arcane Strike is multiplied by the number of times (two, three, or four) you roll damage dice for one of those feats."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=Special Ability,Bloodrager ~ Bloodrage", "PREABILITY:1,CATEGORY=FEAT,Arcane Strike", "PRECLASS:1,SPELLCASTER.Arcane=1"]) },
    FeatTableEntry { key: "Canny Tumble", category: FeatCategory::Combat, name: "Canny Tumble", description: Some("When you use Acrobatics to move through an opponent's threatened area or space without provoking an attack of opportunity from that opponent, you gain a +2 circumstance bonus on your next melee attack roll against that opponent and that opponent is denied its Dexterity bonus to AC, as long as you make that attack before the start of your next turn."), effect: None, prerequisites: Some(&["PREABILITY:2,CATEGORY=FEAT,Dodge,Mobility", "PRESKILL:1,Acrobatics=5"]) },
    FeatTableEntry { key: "Channeling Force", category: FeatCategory::Combat, name: "Channeling Force", description: Some("You distill your channeled energy into a sheen of force that surrounds your weapon for a limited time."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=Special Ability,TYPE.ChannelEnergy", "PRESPELLDESCRIPTOR:1,Force=0"]) },
    FeatTableEntry { key: "Coordinated Shot", category: FeatCategory::Combat, name: "Coordinated Shot", description: Some("If your ally with this feat is threatening an opponent and is not providing cover to that opponent against your ranged attacks, you gain a +1 bonus on ranged attacks against that opponent. If your ally with this feat is flanking that opponent with another ally (even if that other ally doesn't have this feat), this bonus increases to +2."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Point-Blank Shot"]) },
    FeatTableEntry { key: "Counter Reflexes", category: FeatCategory::Combat, name: "Counter Reflexes", description: Some("Opponents with the Mobility feat do not gain the dodge bonus granted by that feat when they provoke attacks of opportunity by moving out of or within your threatened area."), effect: None, prerequisites: Some(&["PREABILITY:3,CATEGORY=FEAT,Dodge,Mobility,Anticipate Dodge", "PREMULT:1,[PRETOTALAB:9],[PREVARGTEQ:MonkFeatQualify,6]"]) },
    FeatTableEntry { key: "Counterpunch", category: FeatCategory::Combat, name: "Counterpunch", description: Some("Once per round, when you are fighting unarmed with both hands free and an opponent misses you with a melee attack, it provokes an attack of opportunity from you. You must use an unarmed strike for this attack of opportunity."), effect: None, prerequisites: Some(&["PREMULT:2,[PREABILITY:3,CATEGORY=FEAT,Combat Reflexes,Weapon Focus (Unarmed Strike),Improved Unarmed Strike],[PREMULT:1,[PRETOTALAB:16],[PRECLASS:1,Brawler=12]]", "PREMULT:1,[PREVARGTEQ:PreStatScore_DEX,18],[PREVARGTEQ:FeatDexRequirement,18]"]) },
    FeatTableEntry { key: "Dazing Fist", category: FeatCategory::Combat, name: "Dazing Fist", description: Some("Dazing Fist forces a foe damaged by your unarmed attack to attempt a DC %1 Fortitude saving throw, in addition to dealing damage normally. You must declare that you are using this feat before you make your attack roll-thus, a failed attack roll ruins the attempt. A defender who fails this saving throw is dazed for 1 round, until just before your next turn. You can use Dazing Fist %2 times per day, but no more than once per round. Constructs, incorporeal creatures, mindless creatures, plants, undead, and creatures that are immune to critical hits cannot be affected by this ability.|CL/2+10+WIS|DazingFistTimes"), effect: Some(&[FeatEffectBonus { qualifiers: &["VAR", "DazingFistTimes", "CL/4"] }]), prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Improved Unarmed Strike", "PREMULT:1,[PREVARGTEQ:PreStatScore_DEX,13],[PREVARGTEQ:FeatDexRequirement,13]", "PRESTAT:1,WIS=13", "PRETOTALAB:4"]) },
    FeatTableEntry { key: "Disheartening Display", category: FeatCategory::Combat, name: "Disheartening Display", description: Some("When you successfully use Dazzling Display against any shaken, frightened, or panicked opponents, their fear increases by one step. An already panicked creature demoralized by this feat cowers. Once affected by this feat, a creature cannot be affected by it again (by you or anyone else) for 24 hours."), effect: None, prerequisites: Some(&["PREMULT:2,[PREABILITY:2,CATEGORY=FEAT,Weapon Focus,Dazzling Display],[PRETOTALAB:6]"]) },
    FeatTableEntry { key: "Distracting Charge", category: FeatCategory::Combat, name: "Distracting Charge", description: Some("When your ally with this feat uses the charge action and hits, you gain a +2 bonus on your next attack roll against the target of that charge. This bonus must be used before your ally's next turn, or it is lost."), effect: None, prerequisites: None },
    FeatTableEntry { key: "Draining Strike", category: FeatCategory::Combat, name: "Draining Strike", description: Some("Draining Strike forces a foe damaged by your unarmed attack to attempt a DC %1 Fortitude saving throw, in addition to dealing damage normally. You must declare that you are using this feat before you make your attack roll-thus, a failed attack roll ruins the attempt. A defender who is fails this saving throw fatigued for 1 minute or until the foe is subject to any spell or effect that heals hit point damage. If you have a base attack bonus of +14 or higher, the target is exhausted for the same duration instead. You can use Draining Strike %2 times per day, but no more than once per round. Constructs, incorporeal creatures, mindless creatures, plants, undead, and creatures that are immune to critical hits cannot be affected by this ability.|CL/2+10+WIS|DrainingStrikeTimes"), effect: Some(&[FeatEffectBonus { qualifiers: &["VAR", "DrainingStrikeTimes", "CL/4"] }]), prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Improved Unarmed Strike", "PREMULT:1,[PREVARGTEQ:PreStatScore_DEX,13],[PREVARGTEQ:FeatDexRequirement,13]", "PRESTAT:1,WIS=13", "PRETOTALAB:8"]) },
    FeatTableEntry { key: "Dual Enhancement", category: FeatCategory::Combat, name: "Dual Enhancement", description: Some("You can enhance two weapons, or both ends of a double weapon, with a single act."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Two-Weapon Fighting", "PREABILITY:1,CATEGORY=Special Ability,Warpriest ~ Sacred Weapon,Divine Bond ~ Celestial Spirit"]) },
    FeatTableEntry { key: "Dueling Cape Deed", category: FeatCategory::Combat, name: "Dueling Cape Deed", description: Some("As a move action, you can wrap a cape that you're wearing around your arm (removing it if necessary), and treat it as a buckler. If you are using the cape in this way, and an opponent misses you with a melee attack, as an immediate action you can spend 1 panache point to release your cape from your arm and entangle your foe in it. The foe can free it by using a full-round action to escape or by destroying the cape; a typical cape has hardness 1 and 3 hit points. You can use this feat with items similar in shape and weight to a cape, such as a cloak or a curtain."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Dodge", "PREMULT:1,[PREABILITY:1,CATEGORY=FEAT,Amateur Swashbuckler],[PREABILITY:1,CATEGORY=Special Ability,TYPE.Panache]", "PRESKILL:1,Sleight of Hand=1"]) },
    FeatTableEntry { key: "Extreme Prejudice", category: FeatCategory::Combat, name: "Extreme Prejudice", description: Some("Your hatred of a particular type of creature has honed your killer instinct."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Seething Hatred", "PREABILITY:1,CATEGORY=Special Ability,Slayer ~ Studied Target", "PREVARGTEQ:SneakAttackDice,3"]) },
    FeatTableEntry { key: "Faerie's Strike", category: FeatCategory::Combat, name: "Faerie's Strike", description: Some("%1 times per day, when you use Vital Strike (or Improved Vital Strike or Greater Vital Strike), your strike saps the strength of your opponent. The creature hit must succeed at a DC %2 Fortitude save or be illuminated as if by faerie fire for 1 minute. You can choose to use this ability as a free action after you hit the target with the attack. This is a supernatural ability.|max(WIS,1)|CL/2+10+WIS"), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Vital Strike", "PREMULT:1,[PREABILITY:1,CATEGORY=FEAT,Nature Magic],[PRECLASS:2,SPELLCASTER=1,Ranger=4],[PRECLASS:2,SPELLCASTER=1,Druid=1],[PRECLASS:2,SPELLCASTER=1,Hunter=1]", "PRESKILL:1,Knowledge (Nature)=5"]) },
    FeatTableEntry { key: "Grabbing Drag", category: FeatCategory::Combat, name: "Grabbing Drag", description: Some("You can move easily with a grappled enemy in tow."), effect: None, prerequisites: Some(&["PREABILITY:2,CATEGORY=FEAT,Grabbing Style,Improved Grapple", "PREMULT:1,[PRETOTALAB:8],[PREVARGTEQ:MonkFeatQualify,4],[PRECLASS:1,Monk=4,Brawler=4]"]) },
    FeatTableEntry { key: "Grabbing Master", category: FeatCategory::Combat, name: "Grabbing Master", description: Some("You can grapple two foes as easily as one."), effect: None, prerequisites: Some(&["PREABILITY:3,CATEGORY=FEAT,Grabbing Drag,Grabbing Style,Improved Grapple", "PREMULT:1,[PRETOTALAB:12],[PREVARGTEQ:MonkFeatQualify,8],[PRECLASS:1,Monk=8,Brawler=8]"]) },
    FeatTableEntry { key: "Grabbing Style", category: FeatCategory::Combat, name: "Grabbing Style", description: Some("You are adept at the one-handed grab."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Improved Grapple", "PREMULT:1,[PRETOTALAB:6],[PREABILITY:1,CATEGORY=Special Ability,Brawler ~ Brawler's Flurry],[PREABILITY:1,CATEGORY=Special Ability,TYPE.Flurry of Blows]"]) },
    FeatTableEntry { key: "Grasping Strike", category: FeatCategory::Combat, name: "Grasping Strike", description: Some("when you use Vital Strike (or Improved Vital Strike or Greater Vital Strike), you cause the foliage in the area to reach out and entangle your foe (as the condition) if it fails a DC %2 Reflex save. The effect lasts for 1 minute or until the enemy breaks free with a successful Strength check or an Escape Artist check (DC = %2), whichever comes first.&nl; You can use this benefit a %1 times per day. You can choose to use this ability as a free action after you hit the enemy with the attack. This is a supernatural ability.|max(WIS,1)|CL/2+10+WIS"), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Vital Strike", "PREMULT:1,[PREABILITY:1,CATEGORY=FEAT,Nature Magic],[PRECLASS:2,SPELLCASTER=1,Ranger=4],[PRECLASS:2,SPELLCASTER=1,Druid=1],[PRECLASS:2,SPELLCASTER=1,Hunter=1]", "PRESKILL:1,Knowledge (Nature)=5"]) },
    FeatTableEntry { key: "Greater Weapon of the Chosen", category: FeatCategory::Combat, name: "Greater Weapon of the Chosen", description: Some("When you use your deity's favored weapon to attempt a single attack with the attack action, you roll two dice for your attack roll and take the higher result. You do not need to use your Weapon of the Chosen feat to gain this feat's benefit.  As usual, the reroll does not apply to any confirmation rolls."), effect: None, prerequisites: Some(&["PREABILITY:3,CATEGORY=FEAT,Improved Weapon of the Chosen,Weapon of the Chosen,Weapon Focus"]) },
    FeatTableEntry { key: "Gruesome Slaughter", category: FeatCategory::Combat, name: "Gruesome Slaughter", description: Some("Creatures you demoralize by using the Killing Flourish feat must succeed at a Fortitude save (DC = %1) or become sickened for 1 minute.|CL/2+10+max(DEX,STR)"), effect: None, prerequisites: Some(&["PREABILITY:2,CATEGORY=FEAT,Killing Flourish,Intimidating Prowess", "PRECLASS:1,Slayer=11", "PRESKILL:1,Intimidate=11"]) },
    FeatTableEntry { key: "Improved Awesome Blow", category: FeatCategory::Combat, name: "Improved Awesome Blow", description: Some("You are skilled at sending your opponents flying."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Power Attack", "PREMULT:1,[PREABILITY:1,CATEGORY=Special Ability,Brawler ~ Awesome Blow,TYPE.AwesomeBlow],[PREABILITY:1,CATEGORY=FEAT,Awesome Blow]", "PRESTAT:1,STR=13"]) },
    FeatTableEntry { key: "Improved Swap Places", category: FeatCategory::Combat, name: "Improved Swap Places", description: Some("When you and your ally use Swap Places, your ally can be up to one size larger or smaller than you, and your movement into the ally's square does not provoke an attack of opportunity. If your ally cannot fit into the space you had been occupying and there are no available adjacent squares to accommodate the rest of the ally's space, the ally must squeeze. Alternatively, as part of its movement, the ally can attempt a bull rush combat maneuver against a creature that occupies a space your ally would occupy, but this bull rush cannot move the creature more than 5 feet."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Swap Places"]) },
    FeatTableEntry { key: "Improved Weapon of the Chosen", category: FeatCategory::Combat, name: "Improved Weapon of the Chosen", description: Some("This feat acts as Weapon of the Chosen, except you gain the benefits on all attacks until the start of your next turn. Your attacks gain a single alignment component of your deity-either chaotic, evil, good, or lawful-for the purpose of overcoming damage reduction. If your deity is neutral with no other alignment components, your attacks instead overcome damage reduction as though your weapon were both cold iron and silver."), effect: None, prerequisites: Some(&["PREABILITY:2,CATEGORY=FEAT,Weapon of the Chosen,Weapon Focus"]) },
    FeatTableEntry { key: "Intercept Charge", category: FeatCategory::Combat, name: "Intercept Charge", description: Some("When an opponent charges your ally with this feat, as an immediate action you can move up to your speed toward any square in the path of the charge. If you end your movement in the path of the charge, the opponent must stop when it becomes adjacent to you and then attack you instead of your ally. Your movement from using this feat counts toward your movement on your next turn."), effect: None, prerequisites: None },
    FeatTableEntry { key: "Jabbing Dancer", category: FeatCategory::Combat, name: "Jabbing Dancer", description: Some("You've learned to bend and shift your body to avoid attacks and reposition yourself advantageously."), effect: None, prerequisites: Some(&["PREABILITY:4,CATEGORY=FEAT,Dodge,Improved Unarmed Strike,Jabbing Style,Mobility", "PREMULT:1,[PRETOTALAB:9],[PREVARGTEQ:MonkFeatQualify,5],[PRECLASS:1,Monk=5,Brawler=5]"]) },
    FeatTableEntry { key: "Jabbing Master", category: FeatCategory::Combat, name: "Jabbing Master", description: Some("Your quick punches become even more lethal."), effect: None, prerequisites: Some(&["PREABILITY:6,CATEGORY=FEAT,Dodge,Improved Unarmed Strike,Jabbing Dancer,Jabbing Style,Mobility,Power Attack", "PREMULT:1,[PRETOTALAB:12],[PREVARGTEQ:MonkFeatQualify,8],[PRECLASS:1,Monk=8,Brawler=8]"]) },
    FeatTableEntry { key: "Jabbing Style", category: FeatCategory::Combat, name: "Jabbing Style", description: Some("A cluster of quick strikes deals more damage than a single roundhouse swing."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Improved Unarmed Strike", "PREMULT:1,[PRETOTALAB:6],[PREABILITY:1,CATEGORY=Special Ability,Brawler ~ Brawler's Flurry],[PREABILITY:1,CATEGORY=Special Ability,TYPE.Flurry of Blows]"]) },
    FeatTableEntry { key: "Kick Up", category: FeatCategory::Combat, name: "Kick Up", description: Some("As long as you have at least one hand free, you can use a swift action to retrieve a single unattended item or weapon that weighs 10 pounds or less from the ground, either in your square or in any adjacent square not occupied or threatened by an enemy. Additionally, when you kick up a weapon and attempt a feint before the end of your turn, you receive a +2 circumstance bonus on the feint attempt."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Acrobatic", "PRECLASS:1,Slayer=1,Swashbuckler=1", "PREMULT:1,[PREVARGTEQ:PreStatScore_DEX,13],[PREVARGTEQ:FeatDexRequirement,13]", "PRESKILL:1,Acrobatics=1"]) },
    FeatTableEntry { key: "Killing Flourish", category: FeatCategory::Combat, name: "Killing Flourish", description: Some("When you reduce your target to below 0 hit points with a melee attack, as a swift action you can attempt an Intimidate check to demoralize all foes within 30 feet who can see your attack."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Intimidating Prowess", "PRECLASS:1,Slayer=4", "PRESKILL:1,Intimidate=4"]) },
    FeatTableEntry { key: "Merciless Butchery", category: FeatCategory::Combat, name: "Merciless Butchery", description: Some("Your talent for slaughter lets you dispatch helpless opponents before they can recover."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Dastardly Finish", "PREABILITY:1,CATEGORY=Special Ability,Slayer ~ Studied Target", "PREVARGTEQ:SneakAttackDice,5"]) },
    FeatTableEntry { key: "Paralyzing Strike", category: FeatCategory::Combat, name: "Paralyzing Strike", description: Some("Paralyzing Strike forces a foe damaged by your unarmed attack to attempt a DC %1 Fortitude saving throw, in addition to dealing damage normally. You must declare that you are using this feat before you make your attack roll-thus, a failed attack roll ruins the attempt. A defender who fails this saving throw is paralyzed for 1 round, until just before your next turn. You can use Paralyzing Strike %2 times per day, but no more than once per round. Constructs, incorporeal creatures, mindless creatures, plants, undead, and creatures that are immune to critical hits cannot be affected by this ability.|CL/2+10+WIS|ParalyzingStrikeTimes"), effect: Some(&[FeatEffectBonus { qualifiers: &["VAR", "ParalyzingStrikeTimes", "CL/4"] }]), prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Improved Unarmed Strike", "PREMULT:1,[PREVARGTEQ:PreStatScore_DEX,13],[PREVARGTEQ:FeatDexRequirement,13]", "PRESTAT:1,WIS=13", "PRETOTALAB:14"]) },
    FeatTableEntry { key: "Pummeling Bully", category: FeatCategory::Combat, name: "Pummeling Bully", description: Some("Your combo has the chance to trip or move your target."), effect: None, prerequisites: Some(&["PREABILITY:4,CATEGORY=FEAT,Improved Reposition,Improved Trip,Improved Unarmed Strike,Pummeling Style", "PREMULT:1,[PRETOTALAB:9],[PREVARGTEQ:MonkFeatQualify,5],[PRECLASS:1,Monk=5,Brawler=5]"]) },
    FeatTableEntry { key: "Pummeling Charge", category: FeatCategory::Combat, name: "Pummeling Charge", description: Some("Your charge ends with a mighty haymaker."), effect: None, prerequisites: Some(&["PREABILITY:2,CATEGORY=FEAT,Improved Unarmed Strike,Pummeling Style", "PREMULT:1,[PRETOTALAB:12],[PREVARGTEQ:MonkFeatQualify,8],[PRECLASS:1,Monk=8,Brawler=8]"]) },
    FeatTableEntry { key: "Pummeling Style", category: FeatCategory::Combat, name: "Pummeling Style", description: Some("Your unarmed strikes weave together in an effortless combo, focusing on the spots you've weakened with the last hit."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Improved Unarmed Strike", "PREMULT:1,[PRETOTALAB:6],[PREABILITY:1,CATEGORY=Special Ability,Brawler ~ Brawler's Flurry,TYPE.Flurry of Blows]"]) },
    FeatTableEntry { key: "Rage Casting", category: FeatCategory::Combat, name: "Rage Casting", description: Some("When you cast a bloodrager spell, as a swift action you can sacrifice some of your life force to augment the spell's potency. You can opt to take up to 1d6 points of damage per spell level of the spell you are casting, choosing the amount of dice before rolling. You cannot overcome this damage in any way, and it cannot be taken from temporary hit points. For each of these damage dice you roll, the DC of the spell you are casting increases by 1."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=Special Ability,Bloodrager ~ Blood Casting", "PRECLASS:1,SPELLCASTER.Arcane=1"]) },
    FeatTableEntry { key: "Raging Absorption", category: FeatCategory::Combat, name: "Raging Absorption", description: Some("While you are bloodraging, if you successfully save against a damaging arcane spell that either targets you or includes you in its area, and you take no damage from that spell, you can absorb a portion of its arcane energy to replenish your bloodrage. You regain 1 round of bloodrage for every 2 levels of the spell you successfully saved against. You cannot use this feat to regain more rounds of bloodrage each day than your daily maximum number of rounds, nor can you ever exceed your maximum number of rounds."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=Special Ability,Bloodrager ~ Bloodrage", "PRECLASS:1,SPELLCASTER.Arcane=2"]) },
    FeatTableEntry { key: "Raging Concentration", category: FeatCategory::Combat, name: "Raging Concentration", description: Some("While in a bloodrage, you gain a +%1 bonus on concentration checks.|BloodrageConBonus"), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=Special Ability,Bloodrager ~ Blood Casting", "PRECLASS:1,SPELLCASTER.Arcane=1"]) },
    FeatTableEntry { key: "Reckless Rage", category: FeatCategory::Combat, name: "Reckless Rage", description: Some("When you use Power Attack while raging or while using raging song, you take an additional -1 penalty on melee attack rolls and combat maneuver checks, and you gain an additional +2 bonus on melee damage rolls. Modify this damage bonus appropriately based on the type of weapon you are using, as normal for Power Attack."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Power Attack", "PREABILITY:1,CATEGORY=Special Ability,TYPE=Rage,TYPE=SkaldRagingSong"]) },
    FeatTableEntry { key: "Recovered Rage", category: FeatCategory::Combat, name: "Recovered Rage", description: Some("Whenever you reduce a foe to 0 or fewer hit points while you are raging or using raging song, you regain 1 round of rage or raging song (your choice if you have both abilities), as long as the number of Hit Dice that foe possesses are equal to or greater than %1. You cannot use this feat to regain more rounds of rage or raging song each day than your daily maximum number of rounds, nor can you ever exceed your maximum number of rounds.|CL/2"), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=Special Ability,TYPE=Rage,TYPE=SkaldRagingSong"]) },
    FeatTableEntry { key: "Riving Strike", category: FeatCategory::Combat, name: "Riving Strike", description: Some("If you have a weapon that is augmented by your Arcane Strike feat, when you damage a creature with an attack made with that weapon, that creature takes a -2 penalty on saving throws against spells and spell-like abilities. This effect lasts for 1 round."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Arcane Strike", "PRECLASS:1,SPELLCASTER.Arcane=1"]) },
    FeatTableEntry { key: "Seething Hatred", category: FeatCategory::Combat, name: "Seething Hatred", description: Some("You've learned to channel your hatred of a particular type of creature into a devastating strike."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=Special Ability,Slayer ~ Studied Target"]) },
    FeatTableEntry { key: "Seize Advantage", category: FeatCategory::Combat, name: "Seize Advantage", description: Some("You can take advantage of your foes when they overcommit on their attacks."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=Special Ability,Swashbuckler ~ Opportune Parry and Riposte"]) },
    FeatTableEntry { key: "Silent Kill", category: FeatCategory::Combat, name: "Silent Kill", description: Some("You are quite adept at killing your prey without making noise or alerting others."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=Special Ability,Slayer Talent ~ Assassinate,Ninja Trick ~ Assassinate", "PRESKILL:1,Stealth=12"]) },
    FeatTableEntry { key: "Skald's Vigor", category: FeatCategory::Combat, name: "Skald's Vigor", description: Some("While maintaining a raging song, you gain fast healing equal to the Strength bonus your song provides, starting in the round after you begin the song. If you stop maintaining your song, the fast healing ends, even if the effects of your song persist."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=Special Ability,TYPE=SkaldRagingSong"]) },
    FeatTableEntry { key: "Slashing Grace", category: FeatCategory::Combat, name: "Slashing Grace", description: Some("Choose one kind of slashing weapon (such as the longsword). When wielding your chosen weapon one-handed, you can treat it as a one-handed piercing melee weapon for all feats and class abilities that require such a weapon (such as a swashbuckler's or a duelist's precise strike) and you can add your Dexterity modifier instead of your Strength modifier to that weapon's damage. The weapon must be one appropriate for your size.You do not gain this benefit while fighting with two weapons or using flurry of blows, or any time another hand is otherwise occupied."), effect: Some(&[FeatEffectBonus { qualifiers: &["WEAPONPROF=%LIST", "DAMAGE", "DEX"] }, FeatEffectBonus { qualifiers: &["WEAPONPROF=%LIST", "DAMAGE", "-STR"] }]), prerequisites: Some(&["PREVAREQ:HasWeaponFinesseFeat,1", "PREABILITY:1,CATEGORY=FEAT,Weapon Focus", "PREMULT:1,[PREVARGTEQ:PreStatScore_DEX,13],[PREVARGTEQ:FeatDexRequirement,13]"]) },
    FeatTableEntry { key: "Slayer's Feint", category: FeatCategory::Combat, name: "Slayer's Feint", description: Some("You can use Acrobatics instead of Bluff to feint in combat."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Combat Expertise", "PREMULT:1,[PRECLASS:1,Slayer=1],[PREABILITY:1,CATEGORY=FEAT,Acrobatic]", "PREMULT:1,[PREVARGTEQ:PreStatScore_DEX,15],[PREVARGTEQ:FeatDexRequirement,15]", "PRESKILL:1,Acrobatics=1"]) },
    FeatTableEntry { key: "Staggering Fist", category: FeatCategory::Combat, name: "Staggering Fist", description: Some("Staggering Fist forces a foe damaged by your unarmed attack to attempt a DC %1 Fortitude saving throw, in addition to dealing damage normally. You must declare that you are using this feat before you make your attack roll-thus, a failed attack roll ruins the attempt. A defender who fails this saving throw is staggered for 1 round, until just before your next turn. You can use Staggering Fist %2 times per day, but no more than once per round. Constructs, incorporeal creatures, mindless creatures, plants, undead, and creatures that are immune to critical hits cannot be affected by this ability.|CL/2+10+WIS|StaggeringFistTimes"), effect: Some(&[FeatEffectBonus { qualifiers: &["VAR", "StaggeringFistTimes", "CL/4"] }]), prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Improved Unarmed Strike", "PREMULT:1,[PREVARGTEQ:PreStatScore_DEX,13],[PREVARGTEQ:FeatDexRequirement,13]", "PRESTAT:1,WIS=13", "PRETOTALAB:2"]) },
    FeatTableEntry { key: "Stouthearted", category: FeatCategory::Combat, name: "Stouthearted", description: Some("While you are maintaining a raging song, if you fail a saving throw against a fear effect, you can expend a round of performing to reroll your saving throw as an immediate action. You must keep this second result, even if it lower."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=Special Ability,TYPE=SkaldRagingSong"]) },
    FeatTableEntry { key: "Twinned Feint", category: FeatCategory::Combat, name: "Twinned Feint", description: Some("As a standard action, you can attempt to feint against a foe within your reach. If you succeed at the feint, you can make an additional feint attempt against a foe that is adjacent to the first one and also within reach. You can attempt only one additional feint per action with this feat. When you use this feat, you take a -2 penalty to your AC until your next turn. If you have the Improved Feint feat, you can use this feat as a move action instead.|!PREABILITY:1,CATEGORY=FEAT,Improved Feint"), effect: None, prerequisites: Some(&["PRESTAT:1,CHA=13"]) },
    FeatTableEntry { key: "Twist Away", category: FeatCategory::Combat, name: "Twist Away", description: Some("You must have Evasion or Improved Evasion to use this feat. While you are wearing light armor or no armor, if you are forced to attempt a Fortitude saving throw, you can use an immediate action to instead attempt a Reflex saving throw (at the same DC). If you succeed at this saving throw and the attack has a reduced effect on a successful save, you avoid the effect entirely. Whether the saving throw is successful or not, you are staggered until the end of your next turn. If you are prevented from becoming staggered, you can't use Twist Away, nor can you ingnore the staggered condition from Twist Away or remove it early."), effect: None, prerequisites: None },
    FeatTableEntry { key: "Undersized Mount", category: FeatCategory::Combat, name: "Undersized Mount", description: Some("You can ride a mount of your own size category, although encumbrance or other factors might limit how you can use this ability."), effect: None, prerequisites: Some(&["PRESKILL:1,Ride=1"]) },
    FeatTableEntry { key: "Weapon of the Chosen", category: FeatCategory::Combat, name: "Weapon of the Chosen", description: Some("As a swift action, you can call upon your deity to guide an attack you make with your deity's favored weapon. On your next attack in that round with that weapon, your weapon counts as magical for the purpose of overcoming damage reduction or striking an incorporeal creature. If your attack misses because of concealment, you can reroll your miss chance one time to see whether you actually hit."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Weapon Focus", "PRECLASS:1,SPELLCASTER.Divine=1", "PRETEXT:Must have Weapon Focus with one of the deity's favored weapons."]) },
    FeatTableEntry { key: "Winter's Strike", category: FeatCategory::Combat, name: "Winter's Strike", description: Some("%1 times per day, when you use Vital Strike (or Improved Vital Strike or Greater Vital Strike), your strike saps the strength of your opponent. The creature hit must succeed at a DC %2 Fortitude save or become fatigued for %3 rounds. You can choose to use this ability as a free action after you hit the target with the attack. This is a supernatural ability.|max(WIS,1)|CL/2+10+WIS|min(WIS,1)"), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Vital Strike", "PREMULT:1,[PREABILITY:1,CATEGORY=FEAT,Nature Magic],[PRECLASS:2,SPELLCASTER=1,Ranger=4],[PRECLASS:2,SPELLCASTER=1,Druid=1],[PRECLASS:2,SPELLCASTER=1,Hunter=1]", "PRESKILL:1,Knowledge (Nature)=5"]) },
    FeatTableEntry { key: "Wounded Paw Gambit", category: FeatCategory::Combat, name: "Wounded Paw Gambit", description: Some("Whenever you use Broken Wing Gambit and an opponent attacks you as a result, each ally who has this feat and is within 30 feet of that opponent can attempt a ranged attack against it as an immediate action. The ally's ranged weapon must be in hand, loaded, and ready to be fired or thrown in order to make this attack possible.&nl; An ally who has this feat and Broken Wing Gambit can instead use Broken Wing Gambit to attempt an attack of opportunity against the foe, but cannot attempt both that attack of opportunity and this ranged attack."), effect: None, prerequisites: Some(&["PREABILITY:1,CATEGORY=FEAT,Broken Wing Gambit", "PRESKILL:1,Bluff=5"]) },
];
